-- GERADO POR fonte/build.js — não edite à mão.
-- Catálogo do curso fr-es, leva 26a6ee74, 90 cards.
-- Aplicar pelo workflow Catálogo do taioe-infra (teste, depois produção), antes do push da leva.

values ('fr-es', '26a6ee74', '90 cards')
on conflict (curso, versao) do nothing;

on conflict (curso, card_id) do update set
  tipo = excluded.tipo, nivel = excluded.nivel, tags = excluded.tags, requer = excluded.requer,
  versao = excluded.versao, alternativas = excluded.alternativas, arquivado_em = null;

update cards.catalogo set arquivado_em = now()
 where curso = 'fr-es' and arquivado_em is null
   and card_id <> all (array['fr-b001', 'fr-b002', 'fr-b003', 'fr-b004', 'fr-b005', 'fr-b006', 'fr-b007', 'fr-b008', 'fr-b009', 'fr-b010', 'fr-b011', 'fr-b012', 'fr-b013', 'fr-b014', 'fr-b015', 'fr-b016', 'fr-b017', 'fr-b018', 'fr-b019', 'fr-b020', 'fr-b021', 'fr-b022', 'fr-b023', 'fr-b024', 'fr-b025', 'fr-b026', 'fr-b027', 'fr-b028', 'fr-b029', 'fr-b030', 'fr-b031', 'fr-b032', 'fr-b033', 'fr-b034', 'fr-b035', 'fr-b036', 'fr-b037', 'fr-b038', 'fr-b039', 'fr-b040', 'fr-p001', 'fr-p002', 'fr-p003', 'fr-p004', 'fr-p005', 'fr-p006', 'fr-p007', 'fr-p008', 'fr-p009', 'fr-p010', 'fr-p011', 'fr-p012', 'fr-p013', 'fr-p014', 'fr-p015', 'fr-p016', 'fr-p017', 'fr-p018', 'fr-p019', 'fr-p020', 'fr-p021', 'fr-p022', 'fr-p023', 'fr-p024', 'fr-p025', 'fr-p026', 'fr-p027', 'fr-p028', 'fr-p029', 'fr-p030', 'fr-p031', 'fr-p032', 'fr-p033', 'fr-p034', 'fr-p035', 'fr-p036', 'fr-p037', 'fr-p038', 'fr-p039', 'fr-p040', 'fr-p041', 'fr-p042', 'fr-p043', 'fr-p044', 'fr-p045', 'fr-p046', 'fr-p047', 'fr-p048', 'fr-p049', 'fr-p050']::text[]);
